// src/systems/calendar.ts
init_constants();
var SEASON_ORDER2 = ["spring", "summer", "autumn", "winter"];
function monthOfYear(t) {
  const seasonIdx = SEASON_ORDER2.indexOf(t.season);
  const monthInSeason = Math.floor((t.week - 1) / GAME.WEEKS_PER_MONTH);
  return seasonIdx * GAME.MONTHS_PER_SEASON + monthInSeason + 1;
}
function weekOfMonth(t) {
  return (t.week - 1) % GAME.WEEKS_PER_MONTH + 1;
}
function isMonthStart(t) {
  return weekOfMonth(t) === 1 && t.day === 1;
}
function totalMonth(t) {
  return (t.year - 1) * GAME.MONTHS_PER_YEAR + monthOfYear(t);
}

