// src/systems/overrideSystem.ts
var OVERRIDE_DURATION_DEFAULT = 14;
var OVERRIDE_STATUS = {
  seclusion: "meditating",
  quest: "questing",
  healing: "injured"
};
function issueOverride(discipleId, command, durationDays = OVERRIDE_DURATION_DEFAULT) {
  const day = useTimeStore.getState().totalDay;
  const ov = {
    discipleId,
    command,
    startedAtDay: day,
    durationDays
  };
  useScheduleStore.getState().setOverride(ov);
  useDiscipleStore.getState().update(discipleId, { status: OVERRIDE_STATUS[command] });
}
function cancelOverride(discipleId) {
  useScheduleStore.getState().clearOverride(discipleId);
  useDiscipleStore.getState().update(discipleId, { status: "training" });
}
function tickOverrideExpiry() {
  const day = useTimeStore.getState().totalDay;
  const overrides = useScheduleStore.getState().overrides;
  for (const id of Object.keys(overrides)) {
    const ov = overrides[id];
    if (day >= ov.startedAtDay + ov.durationDays) {
      useScheduleStore.getState().clearOverride(id);
      const d = useDiscipleStore.getState().disciples[id];
      const stillWounded = (d?.wounds?.length ?? 0) > 0;
      useDiscipleStore.getState().update(id, { status: stillWounded ? "injured" : "training" });
    }
  }
}
function activeOverrideOf(discipleId) {
  const ov = useScheduleStore.getState().overrides[discipleId];
  if (!ov) return null;
  const day = useTimeStore.getState().totalDay;
  if (day >= ov.startedAtDay + ov.durationDays) return null;
  return ov;
}

// src/systems/staminaSystem.ts
function staminaRatioMultiplier(stamina, maxStamina) {
  const max = maxStamina > 0 ? maxStamina : BASE_MAX_STAMINA;
  const ratio = stamina / max;
  if (ratio >= 0.5) return 1;
  if (ratio >= 0.3) return 0.7;
  if (ratio >= 0.1) return 0.4;
  return 0;
}
function staminaLevelIndex(stamina, maxStamina) {
  const max = maxStamina > 0 ? maxStamina : BASE_MAX_STAMINA;
  const ratio = stamina / max;
  if (ratio >= 0.8) return 4;
  if (ratio >= 0.5) return 3;
  if (ratio >= 0.3) return 2;
  if (ratio >= 0.1) return 1;
  return 0;
}
function staminaSceneLabel(stamina, maxStamina) {
  switch (staminaLevelIndex(stamina, maxStamina)) {
    case 4:
      return "\uAE30\uB825 \uC655\uC131";
    case 3:
      return "\uAE30\uC0C9 \uD3C9\uC548";
    case 2:
      return "\uAE30\uC0C9 \uBB34\uAC70\uC6C0";
    case 1:
      return "\uC9C0\uCE5C \uAE30\uC0C9";
    default:
      return "\uC4F0\uB7EC\uC9C8 \uB4EF";
  }
}
var COLLAPSE_REST_DAYS = 3;
var COLLAPSE_TRUST_DELTA = -3;
function triggerCollapse(discipleId) {
  issueOverride(discipleId, "healing", COLLAPSE_REST_DAYS);
  useDiscipleStore.getState().adjustTrust(discipleId, COLLAPSE_TRUST_DELTA);
}

// src/systems/dailyLogSystem.ts
var PROGRESS_GOOD = 5;
var PROGRESS_NORMAL = 2;
function trainingPhrase(name, totalDelta) {
  if (totalDelta <= 0) {
    return {
      text: `${name}\uC740 \uD615\uC744 \uC9DA\uC5C8\uC73C\uB098 \uD55C \uC790\uB9AC\uC5D0\uC11C \uB9F4\uB3CC\uC558\uB2E4.`,
      isPlateau: true
    };
  }
  if (totalDelta < PROGRESS_NORMAL) {
    return {
      text: `${name}\uC774 \uBB34\uACF5\uC758 \uACB0\uC744 \uB354\uB4EC\uC5B4 \uBCF4\uC558\uC73C\uB098 \uC190\uC5D0 \uC7A1\uD788\uC9C0 \uC54A\uC558\uB2E4.`,
      isPlateau: true
    };
  }
  if (totalDelta < PROGRESS_GOOD) {
    return {
      text: `${name}\uC774 \uC790\uC138\uB97C \uD55C\uACB0 \uB2E4\uB4EC\uC5C8\uB2E4.`,
      isPlateau: false
    };
  }
  return {
    text: `${name}\uC758 \uC790\uC138\uC5D0\uC11C \uAD70\uB354\uB354\uAE30\uAC00 \uBE60\uC84C\uB2E4 \u2014 \uD55C \uAC78\uC74C \uB098\uC544\uAC14\uB2E4.`,
    isPlateau: false
  };
}
function buildEntry(report, name) {
  const id = report.discipleId;
  const entries = [];
  if (report.collapsed) {
    entries.push({
      id: `${id}-collapse`,
      kind: "collapse",
      discipleId: id,
      discipleName: name,
      text: `${name}\uC774 \uBB34\uB9AC\uD55C \uB05D\uC5D0 \uC4F0\uB7EC\uC84C\uB2E4 \u2014 \uC0AC\uBD80\uAC00 \uAC70\uB450\uC5B4 \uCE58\uB8CC\uC5D0 \uB4E4\uC600\uB2E4.`
    });
    return entries;
  }
  if (report.overrideCommand === "healing") {
    entries.push({
      id: `${id}-override-healing`,
      kind: "override",
      discipleId: id,
      discipleName: name,
      text: `${name}\uC774 \uCE58\uB8CC\uB97C \uC774\uC5B4\uAC00\uBA70 \uBAB8\uC744 \uCD94\uC2AC\uB800\uB2E4.`
    });
  } else if (report.overrideCommand === "quest") {
    entries.push({
      id: `${id}-override-quest`,
      kind: "override",
      discipleId: id,
      discipleName: name,
      text: `${name}\uC740 \uC758\uB8B0 \uD604\uC7A5\uC5D0\uC11C \uAC15\uD638\uC758 \uBC14\uB78C\uC744 \uB9C8\uC168\uB2E4.`
    });
  } else if (report.overrideCommand === "seclusion") {
    const totalDelta = report.arts.reduce((s, a) => s + a.delta, 0);
    const phrase = trainingPhrase(name, totalDelta);
    entries.push({
      id: `${id}-override-seclusion`,
      kind: phrase.isPlateau ? "plateau" : "training",
      discipleId: id,
      discipleName: name,
      text: `${name}\uC740 \uD3D0\uAD00\uC5D0 \uB4E4\uC5B4 \uC548\uACFC \uB9C8\uC8FC\uC130\uB2E4 \u2014 ${phrase.text.replace(`${name}\uC740 `, "").replace(`${name}\uC774 `, "").replace(`${name}\uC758 `, "")}`
    });
  } else if (report.sparNote) {
    entries.push({
      id: `${id}-spar`,
      kind: "training",
      discipleId: id,
      discipleName: name,
      text: report.sparNote
    });
  } else {
    entries.push(categoryEntry(report, name));
  }
  for (const g of report.statGains) {
    if (g.levelUps <= 0) continue;
    entries.push({
      id: `${id}-growth-${g.statId}`,
      kind: "growth",
      discipleId: id,
      discipleName: name,
      text: `${name}\uC758 ${STAT_LABEL[g.statId]} \uB2E8\uB828\uC774 \uD55C \uB2E8\uACC4 \uBB34\uB974\uC775\uC5C8\uB2E4.`
    });
  }
  const beforeLabel = staminaSceneLabel(report.staminaBefore, report.maxStamina);
  const afterLabel = staminaSceneLabel(report.staminaAfter, report.maxStamina);
  if (beforeLabel !== afterLabel) {
    const dropped = staminaLevelIndex(report.staminaAfter, report.maxStamina) < staminaLevelIndex(report.staminaBefore, report.maxStamina);
    entries.push({
      id: `${id}-stamina`,
      kind: dropped ? "stamina_drop" : "stamina_rise",
      discipleId: id,
      discipleName: name,
      text: dropped ? `${name}\uC758 \uAE30\uC0C9\uC774 ${afterLabel}\uC73C\uB85C \uAC00\uB77C\uC549\uC558\uB2E4.` : `${name}\uC774 \uAE30\uB825\uC744 \uB418\uCC3E\uC544 ${afterLabel}\uC5D0 \uAC00\uAE4C\uC6CC\uC84C\uB2E4.`
    });
  }
  for (const a of report.arts) {
    const art = findMartialArt(a.artId);
    const artName = art?.name ?? a.artId;
    if (a.promoted) {
      const stageLabel = MARTIAL_STAGE_LABEL[a.promoted];
      entries.push({
        id: `${id}-promotion-${a.artId}`,
        kind: "promotion",
        discipleId: id,
        discipleName: name,
        text: `${name}\uC774 ${artName} ${stageLabel} \uACBD\uC9C0\uC5D0 \uC62C\uB790\uB2E4 \u2014 ${a.seong}\uC131.`
      });
    } else if (a.seong > a.seongBefore) {
      entries.push({
        id: `${id}-seong-${a.artId}`,
        kind: "growth",
        discipleId: id,
        discipleName: name,
        text: `${name}\uC758 ${artName}\uC774 ${a.seong}\uC131\uC5D0 \uC62C\uB790\uB2E4.`
      });
    }
  }
  return entries;
}
function categoryEntry(report, name) {
  const id = report.discipleId;
  const what = report.optionLabel ?? "";
  switch (report.category) {
    case "rest":
      return {
        id: `${id}-rest`,
        kind: "rest",
        discipleId: id,
        discipleName: name,
        text: what ? `${name}\uC774 ${what}(\uC73C)\uB85C \uC228\uC744 \uB3CC\uB838\uB2E4.` : `${name}\uC774 \uD479 \uC26C\uBA70 \uAE30\uB825\uC744 \uD68C\uBCF5\uD588\uB2E4.`
      };
    case "physical":
      return {
        id: `${id}-physical`,
        kind: "training",
        discipleId: id,
        discipleName: name,
        text: what ? `${name}\uC774 ${what}(\uC73C)\uB85C \uBAB8\uC744 \uB2E8\uB828\uD588\uB2E4.` : `${name}\uC774 \uBAB8\uC744 \uB2E8\uB828\uD588\uB2E4.`
      };
    case "study":
      return {
        id: `${id}-study`,
        kind: "training",
        discipleId: id,
        discipleName: name,
        text: what ? `${name}\uC774 ${what} \uACF5\uBD80\uC5D0 \uBA38\uB9AC\uB97C \uC2F8\uB9F8\uB2E4.` : `${name}\uC774 \uC11C\uCC45\uC744 \uB4E4\uC5EC\uB2E4\uBCF4\uC558\uB2E4.`
      };
    case "martial":
    default: {
      const totalDelta = report.arts.reduce((s, a) => s + a.delta, 0);
      const phrase = trainingPhrase(name, totalDelta);
      return {
        id: `${id}-training`,
        kind: phrase.isPlateau ? "plateau" : "training",
        discipleId: id,
        discipleName: name,
        text: phrase.text
      };
    }
  }
}
function computeBadges(report) {
  const out = [];
  if (report.collapsed) {
    out.push("collapsed");
    return out;
  }
  if (report.arts.some((a) => a.promoted)) out.push("promoted");
  const ratio = report.maxStamina > 0 ? report.staminaAfter / report.maxStamina : 0;
  if (ratio < 0.1) {
    out.push("low_stamina");
  }
  const totalDelta = report.arts.reduce((s, a) => s + a.delta, 0);
  if (report.category === "martial" && totalDelta > 0 && totalDelta < PROGRESS_NORMAL) {
    out.push("plateau");
  }
  const leveledUp = report.statGains.some((g) => g.levelUps > 0);
  const seongUp = report.arts.some((a) => a.seong > a.seongBefore && !a.promoted);
  if (totalDelta >= PROGRESS_GOOD || leveledUp || seongUp) out.push("good_progress");
  return out;
}
function buildMilestones(reports) {
  const out = [];
  const day = useTimeStore.getState().totalDay;
  const disciples = useDiscipleStore.getState().disciples;
  for (const r of reports) {
    const d = disciples[r.discipleId];
    if (!d) continue;
    if (r.collapsed) {
      out.push({
        id: `${day}-${r.discipleId}-collapse`,
        kind: "collapse",
        discipleId: r.discipleId,
        discipleName: d.name,
        title: "\uC4F0\uB7EC\uC9D0",
        body: `${d.name}\uC774 \uBB34\uB9AC\uD55C \uB05D\uC5D0 \uC4F0\uB7EC\uC84C\uB2E4.
\uC0AC\uBD80\uAC00 \uAC70\uB450\uC5B4 \uCE58\uB8CC\uC5D0 \uB4E4\uC600\uB2E4 \u2014 \uBA70\uCE60 \uAC15\uC81C \uD734\uC2DD.`
      });
    }
    for (const a of r.arts) {
      if (!a.promoted) continue;
      const art = findMartialArt(a.artId);
      const stageLabel = MARTIAL_STAGE_LABEL[a.promoted];
      out.push({
        id: `${day}-${r.discipleId}-promo-${a.artId}`,
        kind: "promotion",
        discipleId: r.discipleId,
        discipleName: d.name,
        artId: a.artId,
        artName: art?.name ?? a.artId,
        newStage: a.promoted,
        title: "\uACBD\uC9C0 \uB3C4\uC57D",
        body: `${d.name}\uC774 ${art?.name ?? a.artId} ${stageLabel} \uACBD\uC9C0\uC5D0 \uC62C\uB790\uB2E4 \u2014 ${a.seong}\uC131.`
      });
    }
  }
  return out;
}
function buildTickArtifacts(reports, dateLabel) {
  const disciples = useDiscipleStore.getState().disciples;
  const entries = [];
  const badges = {};
  for (const r of reports) {
    const d = disciples[r.discipleId];
    if (!d) continue;
    const name = d.name;
    entries.push(...buildEntry(r, name));
    const b = computeBadges(r);
    if (b.length > 0) badges[r.discipleId] = b;
  }
  const day = useTimeStore.getState().totalDay;
  return {
    log: { day, dateLabel, entries },
    badges,
    milestones: buildMilestones(reports)
  };
}

// src/systems/rng.ts
var ambientState = 0;
var ambientSeeded = false;
var entropyCounter = 0;
function freshSeed() {
  const t = Date.now();
  return (t ^ t >>> 11 ^ entropyCounter++ * 2654435761) >>> 0;
}
function ensureSeeded() {
  if (ambientSeeded) return;
  ambientState = freshSeed();
  ambientSeeded = true;
}
function seedAmbient(seed) {
  ambientState = seed >>> 0;
  ambientSeeded = true;
}
function ambientCursor() {
  ensureSeeded();
  return ambientState >>> 0;
}
function random() {
  ensureSeeded();
  ambientState = ambientState + 1831565813 | 0;
  let t = Math.imul(ambientState ^ ambientState >>> 15, 1 | ambientState);
  t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
  return ((t ^ t >>> 14) >>> 0) / 4294967296;
}

