    const w = ev.meta?.winner ?? a;
    const l = ev.meta?.loser ?? b;
    return { headline: `${L(a)}\xB7${L(b)} \uB300\uC804 \uACB0\uCC29`, sub: `${L(w)}\uC774(\uAC00) ${L(l)}\uC744(\uB97C) \uAEBE\uACE0 \uD328\uAD8C\uC744 \uC950\uC5C8\uB2E4` };
