// src/systems/jianghuNews.ts
function pushJianghuNews(title, body, priority = "normal") {
  const day = useTimeStore.getState().totalDay;
  useInboxStore.getState().add({
    id: `jianghu-${day}-${Math.floor(random() * 1e6)}`,
    kind: "rumor",
    title,
    preview: body,
    body,
    priority,
    createdAtDay: day,
    read: false,
    resolved: false,
    payload: { domain: "jianghu_news" }
  });
}

