var clamp9 = (n, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, n));
var RIVAL_SURNAMES = ["\uB0A8\uAD81", "\uBAA8\uC6A9", "\uC81C\uAC08", "\uD33D", "\uD558\uD6C4", "\uC11C\uBB38", "\uB2E8\uBAA9", "\uD669\uBCF4", "\uB3C5\uACE0", "\uC0AC\uACF5"];
var RIVAL_GIVEN = ["\uC138\uC9C4", "\uBB34\uACBD", "\uCC9C\uB958", "\uD55C\uC124", "\uBE44\uC5F0", "\uC18C\uC6B4", "\uBCBD\uD558", "\uC900\uADF9", "\uCCAD\uD604"];
var RIVAL_TITLES = [
  "\uAC80\uD654(\u528D\u82B1)",
  "\uC18C\uB8E1(\u5C0F\u9F8D)",
  "\uBC31\uC758\uC11C\uC0DD",
  "\uADC0\uACAC\uC218",
  "\uCD94\uD63C\uB3C4",
  "\uC625\uBA74\uB791",
  "\uBD81\uCC9C\uC2E0\uAD8C"
];
function eligible(d) {
  return !!d && d.status !== "graduated" && d.status !== "departed" && currentAge(d) >= 14 && realmIndex(d.realm) >= realmIndex("iryu");
}
function pushNews2(title, body, priority = "normal") {
  const day = useTimeStore.getState().totalDay;
  useInboxStore.getState().add({
    id: `tourney-${day}-${Math.floor(random() * 1e6)}`,
    kind: "rumor",
    title,
    preview: body,
    body,
    priority,
    createdAtDay: day,
    read: false,
    resolved: false,
    payload: { domain: "jianghu_news" }
  });
}
function makeRivals(median2, count) {
  const out = [];
  for (let i = 0; i < count; i += 1) {
    const surname = RIVAL_SURNAMES[Math.floor(random() * RIVAL_SURNAMES.length)];
    const given = RIVAL_GIVEN[Math.floor(random() * RIVAL_GIVEN.length)];
    const useTitle = random() < 0.4;
    const name = useTitle ? RIVAL_TITLES[Math.floor(random() * RIVAL_TITLES.length)] : `${surname}${given}`;
    const factor = 0.55 + random() * 1.15;
    const base = Math.max(15, median2) * factor;
    out.push({ name, power: Math.round(base + random() * base * 0.15), isDisciple: false });
  }
  return out;
}
function median(xs) {
  if (xs.length === 0) return 0;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
}
function fameForRank(rank, fieldSize) {
  if (rank === 1) return 16;
  if (rank === 2) return 11;
  if (rank === 3) return 8;
  if (rank <= Math.ceil(fieldSize / 2)) return 4;
  return 1;
}
function ordinal(rank) {
  if (rank === 1) return "\uC7A5\uC6D0(\u58EF\u5143)";
  if (rank === 2) return "\uC544\uC6D0(\u4E9E\u5143)";
  if (rank === 3) return "\uD0D0\uD654(\u63A2\u82B1)";
  return `${rank}\uC704`;
}
function runYoungTalentsTournament() {
  const ds = useDiscipleStore.getState();
  const parts = ds.order.map((id) => ds.disciples[id]).filter(eligible);
  if (parts.length === 0) return;
  const med = median(parts.map((d) => combatPower(d)));
  const rivalCount = Math.max(5, parts.length * 2);
  const luck = () => Math.round((random() - 0.5) * Math.max(10, med) * 0.3);
  const field = [
    ...parts.map((d) => ({
      name: d.name,
      power: combatPower(d) + luck(),
      isDisciple: true,
      discipleId: d.id
    })),
    ...makeRivals(med, rivalCount).map((r) => ({ ...r, power: r.power + luck() }))
  ];
  field.sort((a, b) => b.power - a.power);
  const year = useTimeStore.getState().current.year;
  const lines = [];
  field.forEach((e, idx) => {
    if (!e.isDisciple || !e.discipleId) return;
    const rank = idx + 1;
    const gain = fameForRank(rank, field.length);
    const d = ds.disciples[e.discipleId];
    if (d) ds.update(e.discipleId, { fame: clamp9((d.fame ?? 0) + gain) });
    lines.push(`${e.name} \u2014 ${ordinal(rank)} (\uCD1D ${field.length}\uC778 \uC911)`);
  });
  const champ = field[0];
  const headline2 = champ.isDisciple ? `${year}\uB144 \uC6A9\uBD09\uC9C0\uD68C \u2014 \uC6B0\uB9AC ${champ.name}\uC774 \uC7A5\uC6D0!` : `${year}\uB144 \uC6A9\uBD09\uC9C0\uD68C \u2014 ${champ.name}\uC774 \uC7A5\uC6D0\uC5D0 \uC62C\uB790\uB2E4`;
  const body = `\uC62C\uD574 \uC6A9\uBD09\uC9C0\uD68C\uC5D0 \uAC15\uD638\uC758 \uD6C4\uAE30\uC9C0\uC218 ${field.length}\uC778\uC774 \uBAA8\uC600\uB2E4.

${lines.join("\n")}`;
  pushNews2(headline2, body, champ.isDisciple ? "high" : "normal");
  if (champ.isDisciple && champ.discipleId) {
    playCutscene("tournament_champion", { id: champ.discipleId, name: champ.name });
  }
}

