// src/stores/eventHistoryStore.ts
init_esm();
init_middleware();
init_persistStorage();
var SLICE_LIMIT = 5;
var useEventHistoryStore = create()(
  persist(
    (set, get) => ({
      records: [],
      push: (r) => set((s) => ({
        // 최신이 앞에 오도록 prepend. (sliceFor 가 처음 N개만 읽으면 됨)
        records: [r, ...s.records]
      })),
      sliceFor: (templateId, category) => {
        const { records } = get();
        const sameTemplate = records.filter((r) => r.templateId === templateId).slice(0, SLICE_LIMIT).map(toShort);
        const sameCategory = records.filter((r) => r.category === category).slice(0, SLICE_LIMIT).map(toShort);
        return { sameTemplate, sameCategory };
      },
      reset: () => set({ records: [] })
    }),
    {
      name: "eventHistory",
      storage: createJSONStorage(() => slotAwareStorage),
      version: 1,
      partialize: (s) => ({ records: s.records })
    }
  )
);
function toShort(r) {
  return {
    day: r.day,
    templateId: r.templateId,
    category: r.category,
    tone: r.tone,
    discipleId: r.discipleId,
    discipleName: r.discipleName
  };
}

