// src/stores/activityStore.ts
init_esm();
init_middleware();
init_persistStorage();
var useActivityStore = create()(
  persist(
    (set) => ({
      active: [],
      add: (a) => set((s) => ({ active: [...s.active, a] })),
      updateActive: (id, patch) => set((s) => ({ active: s.active.map((x) => x.id === id ? { ...x, ...patch } : x) })),
      remove: (id) => set((s) => ({ active: s.active.filter((x) => x.id !== id) })),
      reset: () => set({ active: [] })
    }),
    {
      name: "activity",
      storage: createJSONStorage(() => slotAwareStorage),
      version: 1,
      partialize: (s) => ({ active: s.active })
    }
  )
);

