function pickResponse(tone) {
  const pool = ONE_LINER_RESPONSES[tone];
  const idx = Math.floor(random() * pool.length);
  return pool[idx];
}

// src/systems/oneLinerSystem.ts
var ONE_LINER_DAILY_CHANCE = 0.6;
function triggerDailyOneLiner() {
  if (random() >= ONE_LINER_DAILY_CHANCE) return;
  const ds = useDiscipleStore.getState();
  const candidates = ds.order.map((id) => ds.disciples[id]).filter(
    (d) => d != null && (d.status === "training" || d.status === "resting" || d.status === "meditating")
  );
  if (candidates.length === 0) return;
  const disciple = candidates[Math.floor(random() * candidates.length)];
  const others = candidates.filter((d) => d.id !== disciple.id);
  const ctx = buildDiscipleCtx(disciple, others);
  const template = pickContextualOneLiner(ctx);
  if (!template) return;
  const body = fillOneLinerBody(template.body, ctx);
  const day = useTimeStore.getState().totalDay;
  const responses = {
    encourage: pickResponse("encourage"),
    nod: pickResponse("nod"),
    caution: pickResponse("caution"),
    ignore: pickResponse("ignore")
  };
  useInboxStore.getState().add({
    id: `oneliner-${disciple.id}-${day}`,
    kind: "one_liner",
    // 한 마디 (응답 가능)
    title: `${disciple.name}\uC758 \uD55C \uB9C8\uB514`,
    preview: body,
    body,
    priority: "normal",
    createdAtDay: day,
    read: false,
    resolved: false,
    payload: {
      domain: "oneLiner",
      templateId: template.id,
      discipleId: disciple.id,
      responses
    }
  });
}

