var useAchievementStore = create()(
  persist(
    (set, get) => ({
      unlocked: [],
      unlockedArts: [],
      has: (id) => get().unlocked.includes(id),
      unlock: (id) => set((s) => s.unlocked.includes(id) ? s : { unlocked: [...s.unlocked, id] }),
      hasArt: (artId) => get().unlockedArts.includes(artId),
      addArt: (artId) => set((s) => s.unlockedArts.includes(artId) ? s : { unlockedArts: [...s.unlockedArts, artId] })
    }),
    {
      name: "achievements",
      storage: createJSONStorage(() => metaStorage),
      version: 1,
      partialize: (s) => ({ unlocked: s.unlocked, unlockedArts: s.unlockedArts })
    }
  )
);

// src/systems/runSlices/alchemySlice.ts
var alchemySlice = {
  key: "alchemy",
  async save(runId) {
    const s = useAlchemyStore.getState();
    await runs.saveAlchemy(runId, {
      learnedRecipes: s.learnedRecipes,
      activeCrafts: s.activeCrafts,
      firstCrafted: s.firstCrafted,
      labOperational: s.labOperational
    });
  },
  async load(runId) {
    const a = await runs.getAlchemy(runId);
    if (a) {
      useAlchemyStore.getState().hydrate({
        learnedRecipes: a.learnedRecipes ?? [],
        activeCrafts: a.activeCrafts ?? {},
        firstCrafted: a.firstCrafted ?? [],
        labOperational: a.labOperational
      });
    } else {
      useAlchemyStore.getState().reset();
    }
  },
  reset() {
    useAlchemyStore.getState().reset();
  }
};

// src/systems/runSlices/inboxSlice.ts
var inboxSlice = {
  key: "inbox",
  async save(runId) {
    const records = useInboxStore.getState().items.map((it) => ({
      kind: it.kind,
      title: it.title,
      preview: it.preview ?? null,
      body: "body" in it && typeof it.body === "string" ? it.body : null,
      priority: it.priority,
      createdAtDay: it.createdAtDay ?? null,
      read: it.read,
      resolved: it.resolved,
      item: it
    }));
    await runs.saveInbox(runId, records);
  },
  async load(runId) {
    const arr = await runs.getInbox(runId);
    useInboxStore.setState({ items: arr });
  },
  reset() {
    useInboxStore.getState().reset();
  }
};

// src/systems/runSlices/itemsSlice.ts
var itemsSlice = {
  key: "items",
  async save(runId) {
    const records = useItemStore.getState().items.map((it) => ({
      category: it.category,
      itemKey: it.id,
      qty: it.count,
      item: it
    }));
    await runs.saveItems(runId, records);
  },
  async load(runId) {
    const arr = await runs.getItems(runId);
    useItemStore.getState().setAll(arr);
  },
  reset() {
    useItemStore.getState().reset();
  }
};

// src/systems/runSlices/jianghuSlice.ts
var jianghuSlice = {
  key: "jianghu",
  async save(runId) {
    const w = useJianghuStore.getState().world;
    await runs.saveJianghu(runId, { factions: w ?? {}, events: w?.events ?? [] });
  },
  async load(runId) {
    const jh = await runs.getJianghu(runId);
    const w = jh?.factions;
    if (w && w.powers && w.tensions) {
      useJianghuStore.getState().hydrateWorld(w);
    } else {
      useJianghuStore.getState().seedDefaults();
    }
  },
  reset() {
    useJianghuStore.getState().seedDefaults();
  }
};

