// src/stores/npcStore.ts
init_persistStorage();
var useNpcStore = create()(
  persist(
    (set) => ({
      npcs: [],
      hydrate: (list) => set({ npcs: list }),
      seedDefaults: () => set({ npcs: seedRunNpcs() }),
      setStatus: (id, status, note) => set((s) => ({
        npcs: s.npcs.map((n) => n.id === id ? { ...n, status, note: note ?? n.note } : n)
      })),
      reset: () => set({ npcs: [] })
    }),
    {
      name: "npcs",
      storage: createJSONStorage(() => slotAwareStorage)
    }
  )
);

// src/systems/runSlices/npcSlice.ts
var npcSlice = {
  key: "npcs",
  async save(runId) {
    const records = useNpcStore.getState().npcs.map((n) => ({
      npcId: n.id,
      faction: n.faction,
      status: n.status,
      data: n
    }));
    await runs.saveNpcs(runId, records);
  },
  async load(runId) {
    const arr = await runs.getNpcs(runId);
    if (arr.length > 0) {
      useNpcStore.getState().hydrate(arr.map((r) => r.data));
    } else {
      useNpcStore.getState().seedDefaults();
    }
  },
  reset() {
    useNpcStore.getState().seedDefaults();
  }
};

// src/systems/runSlices/index.ts
var RUN_CHILD_SLICES = [
  inboxSlice,
  jianghuSlice,
  alchemySlice,
  itemsSlice,
  npcSlice
];

// src/systems/runSync.ts
function snapshot() {
  const time = useTimeStore.getState();
  const sched = useScheduleStore.getState();
  const sect = useSectStore.getState().sect;
  const master = useMasterStore.getState().master;
  const ds = useDiscipleStore.getState();
  const slot = useGameStore.getState().meta.saveSlot;
  const disciples = ds.order.map((id) => ds.disciples[id]).filter((d) => Boolean(d)).map((d) => ({
    sourceId: d.id,
    name: d.name,
    status: d.status,
    state: d
  }));
  return {
    payload: {
      slot,
      diamonds: useGameStore.getState().diamonds,
      // 다이아(계정 단위 재화 — 연구 즉시 완료 등 편의 소비)
      gameTime: { current: time.current, totalDay: time.totalDay },
      master,
      sect,
      schedule: {
        schedule: sched.schedule,
        individualPatterns: sched.individualPatterns,
        dailyChoice: sched.dailyChoice,
        overrides: sched.overrides,
        lastSnapshot: sched.lastSnapshot
      }
    },
    disciples
  };
}
var saveQueue = Promise.resolve();
async function doSaveCurrentRun() {
  if (!useMasterStore.getState().master) return;
  const { payload, disciples } = snapshot();
  const runId = await runs.saveSlot(payload, disciples);
  for (const slice of RUN_CHILD_SLICES) {
    await slice.save(runId);
  }
}
function saveCurrentRun() {
  const next = saveQueue.then(doSaveCurrentRun, doSaveCurrentRun);
  saveQueue = next.catch(() => {
  });
  return next;
}
var autoSaveEnabled = true;
function setAutoSaveEnabled(enabled) {
  autoSaveEnabled = enabled;
}
function saveCurrentRunSilently() {
  if (!autoSaveEnabled) return;
  saveCurrentRun().catch((e) => {
    if (typeof console !== "undefined") console.warn("[runSync] \uC800\uC7A5 \uC2E4\uD328", e);
  });
}

