// src/systems/achievementSystem.ts
init_martialArts();
init_codexStore();
function buildCtx() {
  const disciples = Object.values(useDiscipleStore.getState().disciples);
  const graduates = useGraduateStore.getState().records;
  const divineHerbs = useItemStore.getState().items.find((i) => i.id === "herb-divine")?.count ?? 0;
  const tally = useTallyStore.getState();
  return { disciples, graduates, divineHerbs, n: tally.n, streak: tally.streak };
}
function grantArtToCodex(artId) {
  const codex = useCodexStore.getState();
  if (codex.hasScroll(artId)) return false;
  const art = findMartialArt(artId);
  if (!art) return false;
  codex.addScroll({
    artId,
    acquiredAtRun: 1,
    acquiredAtDay: useTimeStore.getState().totalDay,
    status: "complete",
    // 업적 보상 — 연구 불필요(업적 자체가 해금)
    researchProgress: 100,
    isTrap: false,
    isIncomplete: false
  });
  return true;
}
function announce(a, unlockedArt) {
  const day = useTimeStore.getState().totalDay;
  const artName = unlockedArt ? findMartialArt(unlockedArt)?.name : void 0;
  const body = artName ? `\uC5C5\uC801 \u300C${a.name}\u300D \uB2EC\uC131. ${a.desc}.
\uC804\uC124 \uBB34\uACF5\uC11C **${artName}**\uC774 \uC601\uAD6C\uD788 \uD574\uAE08\uB418\uC5C8\uB2E4 \u2014 \uB2E4\uC74C \uD68C\uCC28\uBD80\uD130 \uC0AC\uBB38\uC5D0 \uC804\uD574\uC9C4\uB2E4.` : `\uC5C5\uC801 \u300C${a.name}\u300D \uB2EC\uC131. ${a.desc}.`;
  useInboxStore.getState().add({
    id: `ach-${a.id}-${day}`,
    kind: "report",
    title: `\uC5C5\uC801 \uB2EC\uC131 \u2014 ${a.name}`,
    preview: body,
    body,
    priority: artName ? "high" : "normal",
    createdAtDay: day,
    read: false,
    resolved: false,
    payload: { domain: "achievement" }
  });
}
function checkAchievements() {
  const store2 = useAchievementStore.getState();
  const ctx = buildCtx();
  for (const a of ACHIEVEMENTS) {
    if (store2.has(a.id)) continue;
    if (!a.check(ctx)) continue;
    store2.unlock(a.id);
    let granted;
    if (a.unlockArtId) {
      store2.addArt(a.unlockArtId);
      if (grantArtToCodex(a.unlockArtId)) granted = a.unlockArtId;
      else granted = a.unlockArtId;
    }
    announce(a, granted);
  }
}
function seedUnlockedArts() {
  for (const artId of useAchievementStore.getState().unlockedArts) grantArtToCodex(artId);
}

// src/systems/timeSystem.ts
function advanceTurn() {
  const before = useTimeStore.getState().current;
  useTimeStore.getState().advanceDay();
  syncResearch();
  tickOverrideExpiry();
  tickCraft();
  tickElixirAbsorb();
  tickWoundRecovery();
  const time = useTimeStore.getState().current;
  if (time.year > before.year) {
    const m = useMasterStore.getState().master;
    if (m) {
      useMasterStore.getState().update({
        yearsAsMaster: m.yearsAsMaster + 1,
        age: m.age + 1
      });
    }
    tickCareers();
    runYoungTalentsTournament();
    tickReputationInfluence();
  }
  if (time.season !== before.season) {
    tickWorld();
  }
  const master = useMasterStore.getState().master;
  if (master && master.yearsAsMaster >= MASTER.LIFETIME_YEARS) {
    useMasterStore.getState().adjustHealth(-master.health);
    useGameStore.getState().setPhase("ended");
    return;
  }
  if (isMonthStart(time)) {
    tickMonthlyEconomy();
    generateBoard();
    const sched = useScheduleStore.getState();
    if (sched.lastSnapshot) sched.openMonthlyReport();
    sched.setSnapshot(captureSnapshot());
    sched.openMonthlySetup();
    return;
  }
  const reports = tickDailyTraining();
  const dateLabel = buildDateLabel();
  const { log, badges, milestones } = buildTickArtifacts(reports, dateLabel);
  usePendingStore.getState().setDailyTick(log, badges, milestones);
  tickQuests();
  tickActivities();
  tickMasterOutreach();
  const llmDebugs = usePendingStore.getState().llmDebugBuffer;
  usePendingStore.getState().setSettlement({
    dateLabel,
    log,
    badges,
    llmDebugs
  });
}
function triggerPostSettlement() {
  checkGraduations();
  triggerDailyMoralEvent();
  const moral = useMoralEventStore.getState().pending;
  if (moral) {
    moralToInbox(moral);
    useMoralEventStore.getState().clear();
  }
  triggerDailyWish();
  triggerDailyOneLiner();
  triggerDailyMeeting();
  triggerDailySpar();
  triggerDailyRaid();
  triggerDailyMediation();
  tickDarkness();
  tickSimma();
  checkAchievements();
  const milestones = usePendingStore.getState().milestones;
  if (milestones.length > 0) {
    milestonesToInbox(milestones);
    usePendingStore.setState({ milestones: [] });
  }
  saveCurrentRunSilently();
}
var SEASON_LABEL = {
  spring: "\uBD04",
  summer: "\uC5EC\uB984",
  autumn: "\uAC00\uC744",
  winter: "\uACA8\uC6B8"
};
function buildDateLabel() {
  const time = useTimeStore.getState().current;
  const m = monthOfYear(time);
  const w = weekOfMonth(time);
  return `${time.year}\uB144\uCC28 ${SEASON_LABEL[time.season]} ${m}\uC6D4 ${w}\uC8FC\uCC28 ${time.day}\uC77C`;
}

